import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    tot = {}
    cnt = {}
    for i in range(n):
        nm = data[1 + 2 * i]
        sc = int(data[2 + 2 * i])
        tot[nm] = tot.get(nm, 0) + sc
        cnt[nm] = cnt.get(nm, 0) + 1
    best = None
    for nm in tot:
        if best is None:
            best = nm
            continue
        l = tot[nm] * cnt[best]
        r = tot[best] * cnt[nm]
        if l > r or (l == r and nm < best):
            best = nm
    print(best)

